import pytest
from minimum_spanning_tree import minimum_spanning_tree


def _total_weight(edges, weight_by_edge):
    """辅助函数：计算边集合的总权重。"""
    return sum(weight_by_edge[e] for e in edges)


def _vertices(weight_by_edge):
    """辅助函数：从边字典中提取所有顶点。"""
    verts = set()
    for u, v in weight_by_edge:
        verts.add(u)
        verts.add(v)
    return verts


def _is_connected(edges, vertices):
    """辅助函数：判断边集合是否连接所有顶点（并查集）。"""
    if not vertices:
        return True
    parent = {v: v for v in vertices}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    roots = {find(v) for v in vertices}
    return len(roots) == 1


def _has_cycle(edges, vertices):
    """辅助函数：判断边集合是否含环（并查集）。"""
    parent = {v: v for v in vertices}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru == rv:
            return True
        parent[ru] = rv
    return False


