import pytest

from shortest_path_length import shortest_path_length


class Node:
    """测试用节点，具有 successors 属性（前置条件要求）。"""

    def __init__(self, name, successors=None):
        self.name = name
        self.successors = successors if successors is not None else []

    def __repr__(self):
        return "Node({})".format(self.name)

    def __eq__(self, other):
        return isinstance(other, Node) and self.name == other.name

    def __hash__(self):
        return hash(self.name)


def make_graph(edges):
    """根据 (start, goal, length) 三元组列表构造 length_by_edge 与节点集合。

    返回 (length_by_edge, nodes_dict)，其中 nodes_dict 以名字映射到 Node。
    """
    nodes = {}

    def get_node(name):
        if name not in nodes:
            nodes[name] = Node(name)
        return nodes[name]

    length_by_edge = {}
    for start, goal, length in edges:
        s = get_node(start)
        g = get_node(goal)
        length_by_edge[(s, g)] = length
        if g not in s.successors:
            s.successors.append(g)
    return length_by_edge, nodes


def test_shortest_path_length_start_equals_goal_returns_zero():
    """边界：startnode 即 goalnode，规约规定距离为 0。"""
    length_by_edge, nodes = make_graph([])
    a = nodes.get("A") or Node("A")
    assert shortest_path_length(length_by_edge, a, a) == 0


def test_shortest_path_length_empty_graph_start_equals_goal_returns_zero():
    """边界：空图且起点即终点，规约规定距离为 0。"""
    assert shortest_path_length({}, Node("A"), Node("A")) == 0


def test_shortest_path_length_single_edge():
    """正常：单边直达，最短路径长度等于该边长度。"""
    length_by_edge, nodes = make_graph([("A", "B", 5)])
    assert shortest_path_length(length_by_edge, nodes["A"], nodes["B"]) == 5


def test_shortest_path_length_chooses_shorter_of_two_paths():
    """正常：多条路径到达同一节点，应返回较短路径长度。"""
    length_by_edge, nodes = make_graph([
        ("A", "B", 1),
        ("A", "C", 10),
        ("B", "C", 1),
    ])
    assert shortest_path_length(length_by_edge, nodes["A"], nodes["C"]) == 2


def test_shortest_path_length_unreachable_returns_inf():
    """错误/边界：目标不可达，规约规定返回 float('inf')。"""
    length_by_edge, nodes = make_graph([("A", "B", 1)])
    c = Node("C")
